update private.goal_clarification_quotas set available_attempts=20 where owner_id='fc000000-0000-4000-8000-000000000001';
select lives_ok($test$do $body$
declare i integer; turn_id uuid; turn jsonb; result jsonb; revision integer;
begin
 for i in 1..13 loop
  turn_id:=md5('clarification-window-'||i)::uuid;
  perform set_config('role','authenticated',true);
  revision:=(public.read_goal_clarification('fc000000-0000-4000-8000-000000000022')->>'revision')::integer;
  turn:=public.begin_goal_clarification(turn_id,'fc000000-0000-4000-8000-000000000022',revision,'暂停');
  perform set_config('role','service_role',true);
  turn:=public.claim_goal_clarification('fc000000-0000-4000-8000-000000000001',turn_id,turn_id,current_setting('test.clarification_skill')::jsonb)->'turn';
  result:=jsonb_set(current_setting('test.clarification_paused')::jsonb,'{source,turnId}',to_jsonb(turn_id));
  perform public.finish_goal_clarification('fc000000-0000-4000-8000-000000000001',turn_id,turn_id,result);
 end loop;
 perform set_config('role','postgres',true);
end $body$ $test$,'thirteen explicit turns can complete without silently dropping history');
