select throws_ok($$select public.begin_goal_clarification('fc000000-0000-4000-8000-000000000038','fc000000-0000-4000-8000-000000000022',2,chr(160)||chr(11))$$,'22023','CLARIFICATION_INVALID','ECMAScript whitespace-only message is blank');
