select is(public.save_goal_clarification('fc000000-0000-4000-8000-000000000022',3,true,'fc000000-0000-4000-8000-000000000062')#>>'{brief,status}','confirmed','explicit save may confirm manually corrected complete content');
select is(public.save_goal_clarification('fc000000-0000-4000-8000-000000000022',3,true,'fc000000-0000-4000-8000-000000000062')#>>'{session,revision}','4','closing receipt has its own final session revision');
select is((select version from public.blueprints where owner_id='fc000000-0000-4000-8000-000000000001'),0::bigint,'clarification and explicit brief save never create formal Blueprint revision');
