set local role service_role;
select throws_ok($$select public.claim_goal_clarification('fc000000-0000-4000-8000-000000000002','fc000000-0000-4000-8000-000000000032',gen_random_uuid(),current_setting('test.clarification_skill')::jsonb)$$,'P0002','CLARIFICATION_NOT_FOUND','service claim requires the verified matching owner');
select throws_ok($$select public.claim_goal_clarification('fc000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000032',gen_random_uuid(),jsonb_set(current_setting('test.clarification_skill')::jsonb,'{sha256}',to_jsonb(repeat('0',64))))$$,'22023','CLARIFICATION_INVALID_SKILL','Skill digest must match exact UTF8 instructions');
select throws_ok($$select public.claim_goal_clarification('fc000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000032',gen_random_uuid(),jsonb_build_object('name','blueprint-clarify-goal','version','1.0.0','instructions',repeat('😀',16001),'sha256',encode(sha256(convert_to(repeat('😀',16001),'UTF8')),'hex')))$$,'22023','CLARIFICATION_INVALID_SKILL','Skill instruction bound counts UTF16 units');
reset role;
select ok(not has_table_privilege('service_role','public.goal_clarification_sessions','SELECT,INSERT,UPDATE,DELETE,TRUNCATE'),'privileged worker has fixed RPCs, not direct public table permissions');
select * from finish();
rollback;
